import assert from'node:assert/strict';import fs from'node:fs';import crypto from'node:crypto';import{fileURLToPath}from'node:url';
import{loadCommon,assetRoot}from'../load-common.mjs';import{WorkbenchController}from'../Controller.mjs';import{defaultState}from'../../src/State.mjs';
const contract=JSON.parse(fs.readFileSync(new URL('../../UI-CONTRACT.json',import.meta.url))),nativeFetch=globalThis.fetch;
globalThis.fetch=async(url,{signal}={})=>{if(signal?.aborted)throw new DOMException('aborted','AbortError');const data=await fs.promises.readFile(fileURLToPath(url));return new Response(data);};
const loaded=await loadCommon({base:assetRoot});globalThis.fetch=nativeFetch;const{model,localGate}=loaded;model.compute(defaultState());
const controller=new WorkbenchController({model,contract,defaults:defaultState(),localGate}),digest=()=>crypto.createHash('sha256').update(Buffer.from(model.positions.buffer)).digest('hex'),baseline=digest(),positionRef=model.positions,faceRef=model.faces;
assert.equal(controller.catalog.rows.filter(r=>r.catalogScalar).length,1596);assert.equal(controller.catalog.rows.filter(r=>r.group==='anny.translations').length,312);assert.equal(controller.catalog.rows.filter(r=>r.locked).length,37);
const statuses=controller.catalog.rows.filter(r=>r.group==='anny.localChanges').map(r=>controller.status(r));assert.equal(statuses.filter(s=>s.editable).length,254);assert.equal(statuses.filter(s=>s.label==='身体部分生效').length,34);
for(const key of['anny.facialActions:browDownLeft','mhr.expression:0','anny.pose:eye.L.X','anny.translations:eye.R.Z'])assert.equal(controller.status(controller.catalog.byKey.get(key)).editable,true,key);assert.equal(controller.status(controller.catalog.byKey.get('mhr.pose:6')).editable,false);
assert.throws(()=>controller.set('mhr.pose:6',.1));assert.throws(()=>controller.setOwner('expression','unknown'));assert.equal(digest(),baseline);
controller.set('mhr.pose:7',.2);assert.equal(digest(),baseline,'Inactive MHR articulation must not change geometry');assert.equal(controller.state().mhr.pose[7],.2);
controller.setOwner('rig','mhr');assert.notEqual(digest(),baseline,'Selecting MHR must activate saved articulation');controller.setOwner('rig','anny');assert.equal(digest(),baseline,'Returning Anny must restore its own pose');
controller.set('anny.pose:head.X',20);assert.equal(digest(),baseline,'Head rig owned by GNM must suppress saved Anny head rotation');controller.setOwner('headRig','body');assert.notEqual(digest(),baseline);controller.setOwner('headRig','gnm');assert.equal(digest(),baseline);
controller.set('anny.localChanges:nose-width1-incr',.4);assert.equal(digest(),baseline,'Inactive pure head local leaked');controller.setOwner('headShape','anny');assert.notEqual(digest(),baseline);controller.setOwner('headShape','gnm');assert.equal(digest(),baseline);
controller.set('anny.facialActions:jawOpen',.35);assert.equal(digest(),baseline);controller.setOwner('expression','anny');const annyFace=digest();assert.notEqual(annyFace,baseline);controller.setOwner('gaze','rig');controller.set('anny.pose:eye.L.X',12);assert.notEqual(digest(),annyFace);controller.setOwner('expression','gnm');controller.setOwner('gaze','gnm');assert.equal(digest(),baseline);controller.setOwner('expression','mhr');controller.set('mhr.expression:14',.5);const inactiveMHRLook=digest();controller.set('mhr.expression:14',.8);assert.equal(digest(),inactiveMHRLook);controller.setOwner('gaze','expression');assert.notEqual(digest(),inactiveMHRLook);controller.setOwner('expression','gnm');controller.setOwner('gaze','gnm');assert.equal(digest(),baseline);
controller.set('gnm.identity:0',.15);const changed=digest(),archive=controller.archive();assert.notEqual(changed,baseline);controller.resetAll();assert.equal(digest(),baseline);controller.restore(JSON.parse(JSON.stringify(archive)));assert.equal(digest(),changed);assert.equal(controller.state().mhr.pose[7],.2);assert.equal(controller.state().anny.pose.head[0],20);
const before=controller.state();assert.throws(()=>controller.set('anny.phenotypes:age',-1));assert.deepEqual(controller.state(),before);assert.equal(digest(),changed);assert.equal(model.positions,positionRef);assert.equal(model.faces,faceRef);
controller.resetAll();controller.set('anny.phenotypes:age',-1/3);assert.equal(controller.state().anny.phenotypes.age,-1/3);assert.notEqual(digest(),baseline);controller.resetAll();assert.equal(digest(),baseline);
console.log(JSON.stringify({passed:true,actualAssetLoader:true,catalogScalars:1596,extraTranslations:312,locked:37,localEditable:254,semanticHead:true,localPartial:34,archiveAndInactiveDrivers:true,fixedBuffers:true,neutralSHA256:baseline,adapterFingerprint:model.adapterFingerprint},null,2));
